CREATE FUNCTION pg_temp.c11b() RETURNS text LANGUAGE plpgsql AS $qq$
DECLARE
  r text;
  cname text := $q$user_id_for_auth_email (service_role): auth match, unclaimed fallback, stored value ignored$q$;
  a uuid; b uuid; c uuid; i uuid; n uuid; x uuid; y uuid;
  t text; t2 text; e text; st text; ok boolean; j jsonb; j2 jsonb; k int;
BEGIN
  BEGIN

  a := pg_temp.mk('c11b-3998-a@example.test');
  b := pg_temp.mk('c11b-3998-b@example.test');
  PERFORM pg_temp.raw_email(b, 'c11b-3998-probe@example.test');
  n := pg_temp.noauth('C11b-3998-Unclaimed@Example.test');
  PERFORM pg_temp.assvc();
  x := public.user_id_for_auth_email(' C11B-3998-A@example.test');
  y := public.user_id_for_auth_email('c11b-3998-unclaimed@example.test');
  c := public.user_id_for_auth_email('c11b-3998-probe@example.test');
  i := public.user_id_for_auth_email('c11b-3998-nobody@example.test');
  PERFORM pg_temp.pg();
  ok := x = a AND y = n AND c IS NULL AND i IS NULL;
  r := pg_temp.res(ok, 'C11b ' || cname, format('auth=%s unclaimed=%s probe=%s nobody=%s', x = a, y = n, c, i));

    RAISE EXCEPTION USING ERRCODE = 'ZX998', MESSAGE = r;
  EXCEPTION
    WHEN SQLSTATE 'ZX998' THEN RETURN SQLERRM;
    WHEN OTHERS THEN
      PERFORM pg_temp.pg();
      RETURN 'FAIL|C11b ' || cname || '|unexpected ' || SQLSTATE || ' ' || SQLERRM;
  END;
END$qq$;
CREATE FUNCTION pg_temp.c12() RETURNS text LANGUAGE plpgsql AS $qq$
DECLARE
  r text;
  cname text := $q$3991 pre-check (as merged in this branch) passes against the installed handle_new_user$q$;
  a uuid; b uuid; c uuid; i uuid; n uuid; x uuid; y uuid;
  t text; t2 text; e text; st text; ok boolean; j jsonb; j2 jsonb; k int;
BEGIN
  BEGIN

  BEGIN
    EXECUTE $q$DO $pre$
DECLARE
  v_md5 text;
  r     record;
BEGIN
  FOR r IN SELECT * FROM (VALUES
    ('public.member_status_grants_access(text)',  'f9e7a2defaa0de6e96d4feee43527c3c'),
    ('public.member_status_is_deactivated(text)', 'f1cc92b7dd9b6c84778c86dbb89aafcf'),
    ('public.accept_invitation(text,text)',       '37ce05772d72d25439d5ef2bdd5a2d08')
  ) AS t(sig, expected) LOOP
    SELECT md5(p.prosrc) INTO v_md5 FROM pg_proc p WHERE p.oid = to_regprocedure(r.sig);
    IF v_md5 IS DISTINCT FROM r.expected THEN
      RAISE EXCEPTION '3991 pre-check: % body md5 % is not the expected %', r.sig, v_md5, r.expected;
    END IF;
  END LOOP;

  -- handle_new_user: the body before BACKLOG-3998 (20261016070000) or the body it installs.
  SELECT md5(p.prosrc) INTO v_md5 FROM pg_proc p WHERE p.oid = to_regprocedure('public.handle_new_user()');
  IF v_md5 IS NULL OR v_md5 NOT IN ('64c98e28c6916d1095fd70445e7812cf', 'd29adc102b649c9d53f754725feb66b3') THEN
    RAISE EXCEPTION '3991 pre-check: public.handle_new_user() body md5 % is not an expected one', v_md5;
  END IF;

  FOR r IN SELECT * FROM (VALUES
    ('public.sync_profile_names_from_idp(text,text,text)', '984dc45b04f369274a1f003344042cae'),
    ('public.org_names_directory_managed(uuid)',           '99e8d288115addafe005249f42e7d4b8'),
    ('public.set_member_name(uuid,text,text)',             'e6e1590f67f8c15f98fa32a6a94aeffb')
  ) AS t(sig, expected) LOOP
    SELECT md5(p.prosrc) INTO v_md5 FROM pg_proc p WHERE p.oid = to_regprocedure(r.sig);
    IF v_md5 IS NOT NULL AND v_md5 <> r.expected THEN
      RAISE EXCEPTION '3991 pre-check: % exists with a different body (md5 %)', r.sig, v_md5;
    END IF;
  END LOOP;

  IF (SELECT column_default FROM information_schema.columns
       WHERE table_schema = 'public' AND table_name = 'organizations'
         AND column_name = 'jit_provisioning_enabled') IS DISTINCT FROM 'false' THEN
    RAISE EXCEPTION '3991 pre-check: organizations.jit_provisioning_enabled DEFAULT is not false (20261016100100 not applied)';
  END IF;

  IF (SELECT count(*) FROM information_schema.columns
       WHERE table_schema = 'public'
         AND ((table_name = 'organization_members' AND column_name IN ('invited_first_name', 'invited_last_name'))
           OR (table_name = 'scim_tokens' AND column_name IN ('organization_id', 'revoked_at', 'expires_at'))
           OR (table_name = 'organizations' AND column_name IN ('scim_enabled', 'directory_sync_enabled', 'personal_owner_user_id')))) <> 8 THEN
    RAISE EXCEPTION '3991 pre-check: a required column is missing (invited_*_name from 20261017230000, scim_tokens, organizations)';
  END IF;
END $pre$;$q$;
    st := 'ok';
  EXCEPTION WHEN OTHERS THEN st := SQLERRM;
  END;
  r := pg_temp.res(st = 'ok', 'C12 ' || cname, st);

    RAISE EXCEPTION USING ERRCODE = 'ZX998', MESSAGE = r;
  EXCEPTION
    WHEN SQLSTATE 'ZX998' THEN RETURN SQLERRM;
    WHEN OTHERS THEN
      PERFORM pg_temp.pg();
      RETURN 'FAIL|C12 ' || cname || '|unexpected ' || SQLSTATE || ' ' || SQLERRM;
  END;
END$qq$;
CREATE FUNCTION pg_temp.c13() RETURNS text LANGUAGE plpgsql AS $qq$
DECLARE
  r text;
  cname text := $q$auth email change reaches public.users (lowercased)$q$;
